INSERT INTO `vehicle_categories` VALUES (1,'Hatchback','hatchback','car-rear','Agile, economic city hatchbacks ideal for easy parking & daily commutes.'),(2,'Sedan','sedan','car-side','Refined executive sedans offering smooth rides & spacious comfort.'),(3,'SUV','suv','truck-monster','High ground-clearance SUVs built for family trips & highway cruising.'),(4,'4x4 / Off-road','offroad','truck-pickup','Rugged 4WD vehicles engineered for extreme terrains & mountain trails.'),(5,'Electric','electric','bolt','Zero-emission smart electric vehicles with instant torque & tech features.'),(6,'Hybrid','hybrid','leaf','Ultra-efficient strong hybrid vehicles for long range & low emissions.'),(7,'Sports / Performance','sports','gauge-high','Exotic high-performance speedsters delivering pure driving passion.'),(8,'MPV / 7-Seater','mpv','van-shuttle','Spacious 7-8 seater MPVs ideal for large family vacations & group tours.');
/*!40000 ALTER TABLE `vehicle_categories` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `vehicles`
--

DROP TABLE IF EXISTS `vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vehicles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL,
  `location_id` int(11) NOT NULL,
  `brand` varchar(50) NOT NULL,
  `model` varchar(50) NOT NULL,
  `year` int(11) NOT NULL,
  `reg_number` varchar(30) NOT NULL,
  `fuel_type` enum('Petrol','Diesel','Electric','Hybrid') NOT NULL,
  `transmission` enum('Automatic','Manual') NOT NULL,
  `seating_capacity` int(11) NOT NULL,
  `daily_rate` decimal(10,2) NOT NULL,
  `hourly_rate` decimal(10,2) NOT NULL,
  `deposit_amount` decimal(10,2) NOT NULL,
  `status` enum('available','reserved','rented','returned','maintenance') NOT NULL DEFAULT 'available',
  `insurance_expiry` date DEFAULT '2026-12-31',
  `puc_expiry` date DEFAULT '2026-12-31',
  `image_url` varchar(255) NOT NULL,
  `mileage` varchar(50) NOT NULL,
  `description` text NOT NULL,
  `features` text NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reg_number` (`reg_number`),
  KEY `category_id` (`category_id`),
  KEY `location_id` (`location_id`),
  CONSTRAINT `vehicles_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `vehicle_categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vehicles_ibfk_2` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

